// intToStr — templ 표현식에서 int → string. fmt.Sprintf 를 매번 부르지 않기 위한 헬퍼.
func intToStr(n int) string {
	// -128..128 정도 범위. 아이콘 size 인자 전용.
	if n == 0 {
		return "0"
	}
	neg := false
	if n < 0 {
		neg = true
		n = -n
	}
	buf := [4]byte{}
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

